    # Initialize the grid with zeros
    grid = [[0] * N for _ in range(N)]

    # Fill the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize the DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * N + 1)]
    dp[0][0][0] = grid[0][0]

    # Directions for moving down or right
    directions = [(1, 0), (0, 1)]

    # Fill the DP table
    for t in range(1, 2 * N - 1):
        for i1 in range(max(0, t - (N - 1)), min(N, t + 1)):
            j1 = t - i1
            if j1 < 0 or j1 >= N:
                continue
            for i2 in range(max(0, t - (N - 1)), min(N, t + 1)):
                j2 = t - i2
                if j2 < 0 or j2 >= N:
                    continue
                for di1, dj1 in directions:
                    ni1, nj1 = i1 + di1, j1 + dj1
                    if ni1 < 0 or ni1 >= N or nj1 < 0 or nj1 >= N:
                        continue
                    for di2, dj2 in directions:
                        ni2, nj2 = i2 + di2, j2 + dj2
                        if ni2 < 0 or ni2 >= N or nj2 < 0 or nj2 >= N:
